files.defaults.js:
// The defaults every layer reads.
export function defaults() {
  return { host: 'localhost', prot: 8080 };
}

files.config.js:
import { defaults } from './defaults.js';

export function port(env) {
  return (env && Number(env.PORT)) || defaults().port;
}

files.server.js:
import { defaults } from './defaults.js';

export function describe() {
  const d = defaults();
  return d.host + ':' + d.port;
}

files.test.mjs:
import { port } from './config.js';
import { describe } from './server.js';

let bad = 0;
const p = port({});
if (p !== 8080) { console.error('FAIL config.js: port({}) returned ' + p + ' instead of the default 8080. config.js is not reading the default properly.'); bad = 1; }
if (port({ PORT: '3000' }) !== 3000) { console.error('FAIL config.js: the environment is ignored.'); bad = 1; }
const d = describe();
if (d !== 'localhost:8080') { console.error('FAIL server.js: describe() returned ' + d + '. server.js is building the address wrongly.'); bad = 1; }
process.exit(bad);
